#!/usr/bin/env bash
set -euo pipefail

usage() {
  cat <<'EOF'
Run managed-HPC preflight checks for PPVS workflow.

Usage:
  experiments/bootstrap/preflight_cluster.sh --profile <cluster.env> [--strict]

Options:
  --profile PATH   Profile file generated by init_project.sh
  --strict         Fail if SLURM accounting is not configured
  --help           Show this help
EOF
}

PROFILE=""
STRICT=0
while [[ $# -gt 0 ]]; do
  case "$1" in
    --profile) PROFILE="${2:-}"; shift 2 ;;
    --strict) STRICT=1; shift ;;
    --help|-h) usage; exit 0 ;;
    *) echo "Unknown arg: $1" >&2; usage; exit 2 ;;
  esac
done

if [[ -z "${PROFILE}" ]]; then
  echo "--profile is required" >&2
  usage
  exit 2
fi
if [[ ! -f "${PROFILE}" ]]; then
  echo "Profile not found: ${PROFILE}" >&2
  exit 1
fi

# shellcheck disable=SC1090
source "${PROFILE}"

PPVS_ROOT="${PPVS_ROOT:?PPVS_ROOT missing in profile}"
PPVS_EXPERIMENTS_DIR="${PPVS_EXPERIMENTS_DIR:?PPVS_EXPERIMENTS_DIR missing in profile}"
PPVS_PARAMS_DIR="${PPVS_PARAMS_DIR:?PPVS_PARAMS_DIR missing in profile}"
PPVS_RESULTS_DIR="${PPVS_RESULTS_DIR:?PPVS_RESULTS_DIR missing in profile}"
PPVS_RUNS_DIR="${PPVS_RUNS_DIR:?PPVS_RUNS_DIR missing in profile}"

echo "== Host =="
hostname
date -Is
echo "user=${USER}"

echo "== SLURM commands =="
for cmd in scontrol sinfo squeue sbatch srun sacct; do
  command -v "${cmd}" >/dev/null 2>&1 || { echo "Missing command: ${cmd}" >&2; exit 1; }
done
echo "slurm_cli_ok"

echo "== SLURM health =="
scontrol ping
sinfo -s

echo "== Accounting config =="
CFG="$(scontrol show config)"
ACCT_TYPE="$(echo "${CFG}" | awk -F= '/^AccountingStorageType/{print $2}' | xargs)"
JG_TYPE="$(echo "${CFG}" | awk -F= '/^JobAcctGatherType/{print $2}' | xargs)"
JG_FREQ="$(echo "${CFG}" | awk -F= '/^JobAcctGatherFrequency/{print $2}' | xargs)"
echo "AccountingStorageType=${ACCT_TYPE:-unknown}"
echo "JobAcctGatherType=${JG_TYPE:-unknown}"
echo "JobAcctGatherFrequency=${JG_FREQ:-unknown}"

if [[ -z "${ACCT_TYPE}" || "${ACCT_TYPE}" == "accounting_storage/none" ]]; then
  echo "Warning: accounting storage appears disabled." >&2
  if [[ "${STRICT}" -eq 1 ]]; then
    exit 1
  fi
fi

echo "== Runtime paths =="
for d in "${PPVS_ROOT}" "${PPVS_EXPERIMENTS_DIR}" "${PPVS_PARAMS_DIR}" "${PPVS_RESULTS_DIR}" "${PPVS_RUNS_DIR}"; do
  [[ -d "${d}" ]] || { echo "Missing directory: ${d}" >&2; exit 1; }
  touch "${d}/.ppvs_rw_test_$$" 2>/dev/null || { echo "Not writable: ${d}" >&2; exit 1; }
  rm -f "${d}/.ppvs_rw_test_$$"
done
echo "paths_rw_ok"

echo "== Shared path visibility from compute =="
SRUN_ARGS=()
if [[ -n "${SLURM_PARTITION:-}" ]]; then
  SRUN_ARGS+=(--partition "${SLURM_PARTITION}")
fi

srun "${SRUN_ARGS[@]}" -N1 -n1 bash -lc "
  set -e
  test -d '${PPVS_ROOT}'
  test -d '${PPVS_RESULTS_DIR}'
  test -w '${PPVS_RESULTS_DIR}'
  echo compute_shared_ok
"

echo "Preflight completed."
